NativeSignal sys0_is_directory(VM& vm, Thread& thread) {
    const uint32_t address = thread.stack.pop();
    if (address == 0) {
        throw std::runtime_error("Sys0:0x2A path must not be null");
    }
    const std::string text =
        vm.memory().read_cstring(address, thread.base);
    const auto path = host_files::resolve(text, vm.primary_directory());
    thread.stack.push(host_files::is_directory(path) ? 1U : 0U);
    return NativeSignal::Continue;
}
